124:     always_comb begin : mrif_handler_comb
125: 
126:         // Default assignments
127:         // AXI signals
128:         // AW
129:         mem_req_o.aw        = '0;
130:         mem_req_o.aw.id     = 'd2;  // do not change unless you know what you are doing
131:         mem_req_o.aw.addr   = addr_t'(pptr_q);
132:         mem_req_o.aw.len    = 8'b0;
133:         mem_req_o.aw.size   = 3'b011;
134:         mem_req_o.aw.burst  = axi_pkg::BURST_INCR;
135: 
136:         mem_req_o.aw_valid   = 1'b0;
137: 
138:         // W
139:         mem_req_o.w.data    = '0;
140:         mem_req_o.w.strb    = '1;
141:         mem_req_o.w.last    = '0;
142:         mem_req_o.w.user    = '0;
143: 
144:         mem_req_o.w_valid   = 1'b0;
145: 
146:         // B
147:         mem_req_o.b_ready   = 1'b0;
148: 
149:         // AR
150:         mem_req_o.ar        = '0;
151:         mem_req_o.ar.id     = 'd5;  // do not change unless you know what you are doing
152:         mem_req_o.ar.addr   = addr_t'(pptr_q);
153:         mem_req_o.ar.len    = 8'b1;
154:         mem_req_o.ar.size   = 3'b011;
155:         mem_req_o.ar.burst  = axi_pkg::BURST_INCR;
156: 
157:         mem_req_o.ar_valid  = 1'b0;
158: 
159:         // R
160:         mem_req_o.r_ready   = 1'b0;
161: 
162:         fault_valid_o       = 1'b0;
163: 
164:         // Next values
165:         state_n         = state_q;
166:         wr_state_n      = wr_state_q;
167:         pptr_n          = pptr_q;
168:         req_data_n      = req_data_q;
169:         int_id_n        = int_id_q;
170:         mrif_ip_n       = mrif_ip_q;
171:         mrif_ie_n       = mrif_ie_q;
172: 
173:         unique case (state_q)
174: 
175:             // Monitor init signal
176:             IDLE: begin
177: 
178:                 if (req_valid_i) begin
179:                     req_data_n      = req_data_i;
180:                     state_n         = WAIT_INT_ID;
181:                 end
182:             end
183: 
184:             // Validate the interrupt identity and calculate the offset of the IP and IE DWs within the MRIF
185:             WAIT_INT_ID: begin
186: 
187:                 // W handshake
188:                 if (w_valid_i && w_ready_i && w_data_i.last) begin
189:                     // MRIF wdata
190:                     if (req_data_q.mrif_w_cnt == w_cnt_t'(0)) begin
191:                         // Valid interrupt identity
192:                         if ((|w_data_i.data[31:11]) == 1'b0) begin
193:                             pptr_n      = {req_data_q.mrif_data.addr[PLEN-9-1:0], w_data_i.data[10:6], 4'b0};
194:                             int_id_n    = w_data_i.data[10:0];
195:                             state_n     = MEM_ACCESS;
196:                         end
197:                         else begin
198:                             // else ignore transaction
199:                             state_n = IDLE;
200:                         end
201:                     end
202:                     else begin
203:                         req_data_n.mrif_w_cnt = req_data_q.mrif_w_cnt - w_cnt_t'(1);
204:                     end
205:                 end
206:             end
207: 
208:             // Access memory to fetch IP and IE DWs
209:             MEM_ACCESS: begin
210:                 mem_req_o.ar_valid = 1'b1;
211:                 if (mem_resp_i.ar_ready) begin
212:                     state_n = FETCH_MRIF;
213:                 end
214:             end
215: 
216:             // Save IP and IE DWs. Set the corresponding IP bit
217:             FETCH_MRIF: begin
218:

258:             // Write back the IP DW to the MRIF.
259:             WRITE_MRIF: begin
260: 
261:                 unique case (wr_state_q)
262:                     AW_REQ: begin
263:                         mem_req_o.aw_valid  = 1'b1;
264:                         if (mem_resp_i.aw_ready) begin
265:                             wr_state_n  = W_DATA;
266:                         end
267:                     end
268:                     W_DATA: begin
269: 
270:                         mem_req_o.w_valid   = 1'b1;
271:                         mem_req_o.w.last    = 1'b1;
272:                         mem_req_o.w.data    = mrif_ip_q | int_id_bit;
273:                         if(mem_resp_i.w_ready) begin
274:                             wr_state_n  = B_RESP;
275:                         end
276:                     end
277:                     B_RESP: begin
278: 
279:                         if (mem_resp_i.b_valid) begin
280:                             mem_req_o.b_ready   = 1'b1;
281:                             wr_state_n  = AW_REQ;
282: 
283:                             // Check IE bit to determine whether to send notice MSI
284:                             state_n = (|(mrif_ie_q & int_id_bit)) ? (WRITE_NOTICE) : (IDLE);
285: 
286:                             if (mem_resp_i.b.resp != axi_pkg::RESP_OKAY) begin
287:                                 state_n = ERROR;
288:                             end
289:                         end
290:                     end
291: 
292:                     default: state_n = IDLE;
293:                 endcase
294:             end
295: 
296:             // Send MSI notice using input NID and NPPN
297:             WRITE_NOTICE: begin
298:                 
299:                 unique case (wr_state_q)
300:                     AW_REQ: begin
301: 
302:                         mem_req_o.aw_valid  = 1'b1;
303:                         mem_req_o.aw.addr   = addr_t'({req_data_q.mrif_data.nppn[PPNW-1:0], 12'b0});
304:                         mem_req_o.aw.size   = 3'b010;
305:                         if (mem_resp_i.aw_ready) begin
306:                             wr_state_n  = W_DATA;
307:                         end
308:                     end
309:                     W_DATA: begin
310:                         
311:                         mem_req_o.w_valid       = 1'b1;
312:                         mem_req_o.w.strb        = 8'b0000_1111;
313:                         mem_req_o.w.last        = 1'b1;
314:                         mem_req_o.w.data[31:0]  = {21'b0, req_data_q.mrif_data.nid};
315:                         if(mem_resp_i.w_ready) begin
316:                             wr_state_n  = B_RESP;
317:                         end
318:                     end
319:                     B_RESP: begin
320: 
321:                         if (mem_resp_i.b_valid) begin
322:                             mem_req_o.b_ready   = 1'b1;
323:                             state_n             = IDLE;
324: 
325:                             // AXI error
326:                             if (mem_resp_i.b.resp != axi_pkg::RESP_OKAY) begin
327:                                 state_n         = ERROR;
328:                             end
329:                         end
330:                     end
331: 
332:                     default: state_n = IDLE;
333:                 endcase
334:             end
335: 
336:             ERROR: begin
337: 
338:                 mem_req_o.r_ready   = 1'b1;
339:                 fault_valid_o       = 1'b1;
340: 
341:                 if (fault_ready_i) begin
342:                     state_n = IDLE;
343:                 end

